mapper.insert:
insert into company (
    user_id, company_detail_id, location_id, company_img
)
values (
    #{userId}, #{companyDetailId}, #{locationId}, #{companyImg}
)

mapper.select:
select count(*) > 0
from company_detail
where company_name = #{companyName}

select count(*) > 0
from company_follow f
join company c ON f.company_id = c.company_id
where f.company_id = #{companyId}
and f.user_id = #{userId}
and c.is_deleted = false

mapper.update:
update company_detail
set company_name = #{companyName}, company_addr = #{companyAddr},
    company_field = #{companyField}, company_license = #{companyLicense},
    company_as = #{companyAs}, company_career = #{companyCareer},
    company_intro = #{companyIntro}
where company_detail_id = #{companyDetailId}

update company
set company_img = #{companyImg}
where company_id = #{companyId}

update location
set location_addr = #{locationAddr}, location_lat = #{locationLat},
    location_lng = #{locationLng}, location_ac = #{locationAc},
    location_limit = #{locationLimit}
where location_id = #{locationId}

update company
set is_deleted = 1
where company_id = #{companyId}
